    IF bad > 0 OR (SELECT count(*) FROM remediation_change_log WHERE run_stamp = 'import-hero-2026-10-06-007-001-rollback') <> expected THEN
        RAISE EXCEPTION 'import-hero import-hero-2026-10-06-007 - the import image takes the hero flag rollback chunk 001: the journal of this run stamp is not the plan (% unplanned row(s))', bad;
